def getCardsByList(list_id, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("datetime must be string")
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            raise ValueError("invalid datetime")

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            raise ValueError("cursor malformed")
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            raise ValueError("cursor malformed")

    def _log_request(endpoint, status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "trl_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        # If rate_limits.json exists, enforce it. Otherwise no limits.
        cfg = _load("rate_limits.json")
        if not cfg or not isinstance(cfg, list):
            return None
        c = cfg[0] if cfg else {}
        rpm = c.get("requests_per_minute")
        qpd = c.get("requests_per_day")
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rpm, int) and rpm > 0:
            cutoff = (now - datetime.timedelta(minutes=1)).isoformat()
            recent = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd > 0:
            cutoff = (now - datetime.timedelta(days=1)).isoformat()
            recent = 0
            for r in logs:
                ts = r.get("created_at")
                if isinstance(ts, str) and ts >= cutoff:
                    recent += 1
            if recent >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs
    if not isinstance(list_id, str) or not re.match(r"^trl_lst_[0-9A-Z]{18,}$", list_id):
        err = _err("VALIDATION_ERROR", "Invalid list_id", field="list_id")
        _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            err = _err("VALIDATION_ERROR", "Unsupported status", field="status")
            _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit; must be 1–200", field="limit")
        _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    supported_sort = ("position", "-position", "created_at", "-created_at", "updated_at", "-updated_at", "due_at", "-due_at")
    if sort is None:
        sort = "position"
    if not isinstance(sort, str) or sort not in supported_sort:
        err = _err("VALIDATION_ERROR", "Unsupported sort", field="sort")
        _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    cursor_obj = None
    if cursor is not None:
        try:
            cursor_obj = _b64d(cursor)
        except ValueError:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != "getCardsByList":
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err
        if cursor_obj.get("list_id") != list_id or cursor_obj.get("sort") != sort or cursor_obj.get("status") != (status or None):
            err = _err("VALIDATION_ERROR", "Cursor does not match the request", field="cursor")
            _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err
        if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getCardsByList", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err

    # Rate/quota enforcement (if configured)
    limerr = _enforce_limits()
    if limerr:
        _log_request("getCardsByList", limerr["error"]["code"], meta={"list_id": list_id})
        return limerr

    boards = _load("boards.json")
    lists = _load("lists.json")
    cards = _load("cards.json")

    # Resolve default board
    default_board = None
    if isinstance(boards, list):
        for b in boards:
            if isinstance(b, dict) and b.get("default") is True:
                default_board = b
                break
    if not default_board:
        err = _err("UNAUTHORIZED", "No configured board available")
        _log_request("getCardsByList", "UNAUTHORIZED", meta={"list_id": list_id})
        return err

    # Validate list exists and is on default board
    lst = None
    if isinstance(lists, list):
        for l in lists:
            if isinstance(l, dict) and l.get("id") == list_id:
                lst = l
                break
    if not lst:
        err = _err("NOT_FOUND", "List not found", list_id=list_id)
        _log_request("getCardsByList", "NOT_FOUND", meta={"list_id": list_id})
        return err

    if lst.get("board_id") != default_board.get("id"):
        err = _err("UNAUTHORIZED", "List is not accessible on the configured board", list_id=list_id)
        _log_request("getCardsByList", "UNAUTHORIZED", meta={"list_id": list_id})
        return err

    # Per rules: do not return cards for archived lists (no toggle on this surface)
    if lst.get("status") != "active":
        result = {
            "cards": [],
            "list_id": list_id,
            "limit": limit,
            "total": 0,
            "has_more": False,
            "next_cursor": None,
            "sort": sort,
            "status": status
        }
        _log_request("getCardsByList", "OK", meta={"list_id": list_id, "total": 0})
        return result

    want_status = status or "active"

    # Filter to list + board and card status
    rows = []
    if isinstance(cards, list):
        for c in cards:
            if not isinstance(c, dict):
                continue
            if c.get("list_id") != list_id:
                continue
            if c.get("board_id") != default_board.get("id"):
                continue
            if c.get("status") != want_status:
                continue
            # Integrity: list_id must reference list with matching board_id (already ensured for requested list)
            rows.append(c)

    # Sorting
    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _sort_key_card(c):
        if key in ("created_at", "updated_at", "due_at"):
            v = c.get(key)
            if v is None:
                # place None last for asc, first for desc (typical)
                return (1 if not desc else -1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
            try:
                dt = _parse_dt(v)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except ValueError:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (0, dt)
        if key == "position":
            v = c.get("position")
            try:
                return (0, float(v))
            except Exception:
                return (1, 0.0)
        return (0, str(c.get(key) or ""))

    rows.sort(key=_sort_key_card, reverse=desc)

    offset = cursor_obj["offset"] if cursor_obj else 0
    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64e({"v": 1, "endpoint": "getCardsByList", "list_id": list_id, "status": status or None, "sort": sort, "offset": next_offset}) if has_more else None

    result = {
        "cards": page,
        "list_id": list_id,
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "status": status
    }
    _log_request("getCardsByList", "OK", meta={"list_id": list_id, "returned": len(page), "total": total})
    return result

def getLists(board_id=None, status=None, limit=None, cursor=None, sort=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("datetime must be string")
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        return datetime.datetime.fromisoformat(s)

    def _b64e(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64d(s):
        if not isinstance(s, str) or not s:
            raise ValueError("cursor malformed")
        pad = "=" * ((4 - (len(s) % 4)) % 4)
        raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
        return json.loads(raw.decode("utf-8"))

    def _log_request(endpoint, status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "trl_req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("rate_limits.json")
        if not cfg or not isinstance(cfg, list):
            return None
        c = cfg[0] if cfg else {}
        rpm = c.get("requests_per_minute")
        qpd = c.get("requests_per_day")
        now = datetime.datetime.now(datetime.timezone.utc)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rpm, int) and rpm > 0:
            cutoff = (now - datetime.timedelta(minutes=1)).isoformat()
            recent = sum(1 for r in logs if isinstance(r, dict) and isinstance(r.get("created_at"), str) and r["created_at"] >= cutoff)
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd > 0:
            cutoff = (now - datetime.timedelta(days=1)).isoformat()
            recent = sum(1 for r in logs if isinstance(r, dict) and isinstance(r.get("created_at"), str) and r["created_at"] >= cutoff)
            if recent >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs
    if board_id is not None:
        if not isinstance(board_id, str) or not re.match(r"^trl_brd_[0-9A-Z]{18,}$", board_id):
            err = _err("VALIDATION_ERROR", "Invalid board_id", field="board_id")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            err = _err("VALIDATION_ERROR", "Unsupported status", field="status")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err

    if limit is None:
        limit = 200
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit; must be 1–200", field="limit")
        _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
        return err

    supported_sort = ("position", "-position", "created_at", "-created_at", "updated_at", "-updated_at")
    if sort is None:
        sort = "position"
    if not isinstance(sort, str) or sort not in supported_sort:
        err = _err("VALIDATION_ERROR", "Unsupported sort", field="sort")
        _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
        return err

    cursor_obj = None
    if cursor is not None:
        try:
            cursor_obj = _b64d(cursor)
        except Exception:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != "getLists":
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if cursor_obj.get("board_id") != (board_id or None) or cursor_obj.get("sort") != sort or cursor_obj.get("status") != (status or None):
            err = _err("VALIDATION_ERROR", "Cursor does not match the request", field="cursor")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getLists", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err

    limerr = _enforce_limits()
    if limerr:
        _log_request("getLists", limerr["error"]["code"], meta={"board_id": board_id})
        return limerr

    boards = _load("boards.json")
    lists = _load("lists.json")

    # Resolve board: requested or default
    board = None
    if board_id is None:
        if isinstance(boards, list):
            for b in boards:
                if isinstance(b, dict) and b.get("default") is True:
                    board = b
                    break
        if not board:
            err = _err("UNAUTHORIZED", "No configured board available")
            _log_request("getLists", "UNAUTHORIZED", meta={"board_id": board_id})
            return err
    else:
        if isinstance(boards, list):
            for b in boards:
                if isinstance(b, dict) and b.get("id") == board_id:
                    board = b
                    break
        if not board:
            err = _err("NOT_FOUND", "Board not found", board_id=board_id)
            _log_request("getLists", "NOT_FOUND", meta={"board_id": board_id})
            return err

    # Default business rule: when no status provided, getLists returns active lists on default board ordered by position.
    # For explicit status or explicit board_id, apply requested filters.
    if status is None and board_id is None:
        want_status = "active"
    else:
        want_status = status  # could be None => no filter

    rows = []
    if isinstance(lists, list):
        for l in lists:
            if not isinstance(l, dict):
                continue
            if l.get("board_id") != board.get("id"):
                continue
            if want_status is not None and l.get("status") != want_status:
                continue
            # If default call, still only active lists per rule (want_status already "active")
            rows.append(l)

    desc = sort.startswith("-")
    key = sort[1:] if desc else sort

    def _sort_key_list(l):
        if key in ("created_at", "updated_at"):
            v = l.get(key)
            if v is None:
                return (1 if not desc else -1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
            try:
                dt = _parse_dt(v)
                if dt.tzinfo is None:
                    dt = dt.replace(tzinfo=datetime.timezone.utc)
            except Exception:
                dt = datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
            return (0, dt)
        if key == "position":
            v = l.get("position")
            try:
                return (0, float(v))
            except Exception:
                return (1, 0.0)
        return (0, str(l.get(key) or ""))

    rows.sort(key=_sort_key_list, reverse=desc)

    offset = cursor_obj["offset"] if cursor_obj else 0
    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64e({"v": 1, "endpoint": "getLists", "board_id": board_id or None, "status": status or None, "sort": sort, "offset": next_offset}) if has_more else None

    result = {
        "lists": page,
        "board_id": board.get("id"),
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort,
        "status": status if status is not None else (None if board_id is not None else "active")
    }
    _log_request("getLists", "OK", meta={"board_id": board.get("id"), "returned": len(page), "total": total})
    return result

