    if limit is None:
        limit = 50  # server-side default when omitted
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        err = _err("VALIDATION_ERROR", "Invalid limit; must be 1–200", field="limit")
        _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
        return err

    if sort is None:
        sort = "-created_at"
    if not isinstance(sort, str) or sort not in ("created_at", "-created_at"):
        err = _err("VALIDATION_ERROR", "Unsupported sort", field="sort")
        _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
        return err

    cursor_obj = None
    if cursor is not None:
        try:
            cursor_obj = _b64d(cursor)
        except Exception:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if not isinstance(cursor_obj, dict) or cursor_obj.get("v") != 1 or cursor_obj.get("endpoint") != "getRecentActivity":
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if cursor_obj.get("board_id") != (board_id or None) or cursor_obj.get("sort") != sort:
            err = _err("VALIDATION_ERROR", "Cursor does not match the request", field="cursor")
            _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if cursor_obj.get("event_type") != (event_type or None) or cursor_obj.get("actor_member_id") != (actor_member_id or None) or cursor_obj.get("list_id") != (list_id or None) or cursor_obj.get("card_id") != (card_id or None):
            err = _err("VALIDATION_ERROR", "Cursor does not match the request", field="cursor")
            _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err
        if not isinstance(cursor_obj.get("offset"), int) or cursor_obj["offset"] < 0:
            err = _err("VALIDATION_ERROR", "Cursor is malformed", field="cursor")
            _log_request("getRecentActivity", "VALIDATION_ERROR", meta={"board_id": board_id})
            return err

    limerr = _enforce_limits()
    if limerr:
        _log_request("getRecentActivity", limerr["error"]["code"], meta={"board_id": board_id})
        return limerr

    boards = _load("boards.json")
    events = _load("activity_events.json")

    # Resolve board: requested or default
    board = None
    if board_id is None:
        if isinstance(boards, list):
            for b in boards:
                if isinstance(b, dict) and b.get("default") is True:
                    board = b
                    break
        if not board:
            err = _err("UNAUTHORIZED", "No configured board available")
            _log_request("getRecentActivity", "UNAUTHORIZED", meta={"board_id": board_id})
            return err
    else:
        if isinstance(boards, list):
            for b in boards:
                if isinstance(b, dict) and b.get("id") == board_id:
                    board = b
                    break
        if not board:
            err = _err("NOT_FOUND", "Board not found", board_id=board_id)
            _log_request("getRecentActivity", "NOT_FOUND", meta={"board_id": board_id})
            return err

    rows = []
    if isinstance(events, list):
        for e in events:
            if not isinstance(e, dict):
                continue
            if e.get("board_id") != board.get("id"):
                continue
            if event_type is not None and e.get("event_type") not in set(event_type):
                continue
            if actor_member_id is not None and e.get("actor_member_id") != actor_member_id:
                continue
            if list_id is not None and e.get("list_id") != list_id:
                continue
            if card_id is not None and e.get("card_id") != card_id:
                continue
            rows.append(e)

    desc = sort.startswith("-")

    def _sort_key_event(e):
        v = e.get("created_at")
        if v is None:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
        try:
            dt = _parse_dt(v)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt
        except Exception:
            return datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)

    rows.sort(key=_sort_key_event, reverse=desc)

    offset = cursor_obj["offset"] if cursor_obj else 0
    total = len(rows)
    page = rows[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = _b64e({
        "v": 1,
        "endpoint": "getRecentActivity",
        "board_id": board_id or None,
        "event_type": event_type or None,
        "actor_member_id": actor_member_id or None,
        "list_id": list_id or None,
        "card_id": card_id or None,
        "sort": sort,
        "offset": next_offset
    }) if has_more else None

    result = {
        "events": page,
        "board_id": board.get("id"),
        "limit": limit,
        "total": total,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "sort": sort
    }
    _log_request("getRecentActivity", "OK", meta={"board_id": board.get("id"), "returned": len(page), "total": total})
    return result

def addCard(list_id, title, description=None, position=None, due_at=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _now_iso():
        return _now().isoformat()

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            raise ValueError("due_at must be string")
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat()
        except Exception:
            raise ValueError("invalid datetime")

    def _log_request(endpoint, status_code, credential_id=None, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": "trl_req_" + _now().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": endpoint,
            "credential_id": credential_id,
            "status": status_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _now_iso(),
            "meta": meta or {}
        }
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits():
        cfg = _load("rate_limits.json")
        if not cfg or not isinstance(cfg, list):
            return None
        c = cfg[0] if cfg else {}
        rpm = c.get("requests_per_minute")
        qpd = c.get("requests_per_day")
        now = _now()
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        if isinstance(rpm, int) and rpm > 0:
            cutoff = (now - datetime.timedelta(minutes=1)).isoformat()
            recent = sum(1 for r in logs if isinstance(r, dict) and isinstance(r.get("created_at"), str) and r["created_at"] >= cutoff)
            if recent >= rpm:
                return _err("RATE_LIMIT", "Rate limit exceeded")
        if isinstance(qpd, int) and qpd > 0:
            cutoff = (now - datetime.timedelta(days=1)).isoformat()
            recent = sum(1 for r in logs if isinstance(r, dict) and isinstance(r.get("created_at"), str) and r["created_at"] >= cutoff)
            if recent >= qpd:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded")
        return None

    # Validate inputs
    if not isinstance(list_id, str) or not re.match(r"^trl_lst_[0-9A-Z]{18,}$", list_id):
        err = _err("VALIDATION_ERROR", "Invalid list_id", field="list_id")
        _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    if not isinstance(title, str) or len(title.strip()) < 1:
        err = _err("VALIDATION_ERROR", "Title must be a non-empty string", field="title")
        _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err
    title = title.strip()

    if description is not None and not isinstance(description, str):
        err = _err("VALIDATION_ERROR", "Description must be a string", field="description")
        _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    if position is not None and not isinstance(position, (int, float)):
        err = _err("VALIDATION_ERROR", "Position must be a number", field="position")
        _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    due_iso = None
    if due_at is not None:
        try:
            due_iso = _parse_dt(due_at)
        except ValueError:
            err = _err("VALIDATION_ERROR", "due_at must be a valid ISO-8601 datetime", field="due_at")
            _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
            return err

    limerr = _enforce_limits()
    if limerr:
        _log_request("addCard", limerr["error"]["code"], meta={"list_id": list_id})
        return limerr

    boards = _load("boards.json")
    lists = _load("lists.json")
    cards = _load("cards.json")
    members = _load("members.json")
    events = _load("activity_events.json")

    # Resolve default board
    default_board = None
    if isinstance(boards, list):
        for b in boards:
            if isinstance(b, dict) and b.get("default") is True:
                default_board = b
                break
    if not default_board:
        err = _err("UNAUTHORIZED", "No configured board available")
        _log_request("addCard", "UNAUTHORIZED", meta={"list_id": list_id})
        return err

    # Resolve authenticated actor member (ambient auth)
    actor = None
    if isinstance(members, list):
        for m in members:
            if isinstance(m, dict) and m.get("is_authenticated_user") is True and m.get("status") == "active":
                actor = m
                break
    if not actor:
        err = _err("UNAUTHORIZED", "No authenticated member available")
        _log_request("addCard", "UNAUTHORIZED", meta={"list_id": list_id})
        return err

    # Validate list exists, active, and on default board
    lst = None
    if isinstance(lists, list):
        for l in lists:
            if isinstance(l, dict) and l.get("id") == list_id:
                lst = l
                break
    if not lst:
        err = _err("NOT_FOUND", "List not found", list_id=list_id)
        _log_request("addCard", "NOT_FOUND", meta={"list_id": list_id})
        return err

    if lst.get("board_id") != default_board.get("id"):
        err = _err("UNAUTHORIZED", "List is not accessible on the configured board", list_id=list_id)
        _log_request("addCard", "UNAUTHORIZED", meta={"list_id": list_id})
        return err

    if lst.get("status") != "active":
        err = _err("INVALID_TRANSITION", "Cannot add card to an archived list", list_id=list_id, from_status=lst.get("status"), to_status="active")
        _log_request("addCard", "INVALID_TRANSITION", meta={"list_id": list_id})
        return err

    # Compute position
    max_pos = None
    if isinstance(cards, list):
        for c in cards:
            if not isinstance(c, dict):
                continue
            if c.get("list_id") == list_id:
                try:
                    p = float(c.get("position"))
                except Exception:
                    continue
                if max_pos is None or p > max_pos:
                    max_pos = p
    computed_pos = (max_pos + 1.0) if max_pos is not None else 0.0
    final_pos = float(position) if position is not None else computed_pos
    if final_pos < 0:
        err = _err("VALIDATION_ERROR", "position must be >= 0", field="position")
        _log_request("addCard", "VALIDATION_ERROR", meta={"list_id": list_id})
        return err

    now_iso = _now_iso()
    new_id = "trl_crd_" + _now().strftime("%Y%m%d%H%M%S%f")

    new_card = {
        "id": new_id,
        "board_id": default_board.get("id"),
        "list_id": list_id,
        "title": title,
        "description": description,
        "position": final_pos,
        "due_at": due_iso,
        "status": "active",
        "archived_at": None,
        "created_by_member_id": actor.get("id"),
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Persist card
    if not isinstance(cards, list):
        cards = []
    cards.append(new_card)
    _save("cards.json", cards)

    # Activity event: card.created
    if not isinstance(events, list):
        events = []
    ev_id = "trl_evt_" + _now().strftime("%Y%m%d%H%M%S%f")
    events.append({
        "id": ev_id,
        "board_id": default_board.get("id"),
        "actor_member_id": actor.get("id"),
        "event_type": "card.created",
        "list_id": None,
        "card_id": new_id,
        "payload": {
            "list_id": list_id,
            "title": title
        },
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("activity_events.json", events)

    result = {"card": new_card}
    _log_request("addCard", "OK", meta={"list_id": list_id, "card_id": new_id})
    return result

def updateCard(card_id, title=None, description=None, position=None, due_at=None, status=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _parse_dt(s):
        if s is None:
            return None, True
        if not isinstance(s, str):
            return None, False
        try:
            s2 = s[:-1] + "+00:00" if s.endswith("Z") else s
            datetime.datetime.fromisoformat(s2)
            return s, True
        except Exception:
            return None, False

    def _new_id(prefix):
        import secrets
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + secrets.token_hex(6).upper()

    def _find_default_board(boards_rows):
        if not isinstance(boards_rows, list):
            return None
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True and x.get("status") == "active"), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("status") == "active"), None)
        if b:
            return b
        return boards_rows[0] if boards_rows else None

    def _find_actor(members_rows):
        if not isinstance(members_rows, list):
            return None
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if a:
            return a
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("status") == "active"), None)
        if a:
            return a
        return members_rows[0] if members_rows else None

    def _log_activity(activity_rows, board_id, actor_id, event_type, list_id_val, card_id_val, payload, status_code):
        # No dedicated request log collection in schema; record service dynamics here.
        if not isinstance(activity_rows, list):
            return
        activity_rows.append({
            "id": _new_id("trl_act_"),
            "board_id": board_id,
            "actor_member_id": actor_id,
            "event_type": event_type,
            "list_id": list_id_val,
            "card_id": card_id_val,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        })

    boards = _load("boards.json")
    members = _load("members.json")
    lists = _load("lists.json")
    cards = _load("cards.json")
    activity = _load("activity_events.json")

    default_board = _find_default_board(boards)
    actor = _find_actor(members)
    actor_id = actor.get("id") if isinstance(actor, dict) else None
    default_board_id = default_board.get("id") if isinstance(default_board, dict) else None

    # Validate inputs
    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-Z]{18,}$", card_id):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, None,
                          {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "card_id must be a valid trl_crd_... id", field="card_id")

    if title is not None:
        if not isinstance(title, str) or len(title) < 1:
            if isinstance(activity, list) and default_board_id:
                _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                              {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "title", "latency_ms": _lat_ms()}, "error")
                _save("activity_events.json", activity)
            return _err("VALIDATION_ERROR", "title must be a non-empty string when provided", field="title")

    if description is not None and not isinstance(description, str):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                          {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "description", "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "description must be a string when provided", field="description")

    if position is not None:
        if not isinstance(position, (int, float)) or isinstance(position, bool):
            if isinstance(activity, list) and default_board_id:
                _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                              {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "position", "latency_ms": _lat_ms()}, "error")
                _save("activity_events.json", activity)
            return _err("VALIDATION_ERROR", "position must be a number when provided", field="position")

    parsed_due, ok_due = _parse_dt(due_at)
    if due_at is not None and not ok_due:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                          {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "due_at", "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "due_at must be an ISO-8601 datetime string or null", field="due_at")

    if status is not None:
        if not isinstance(status, str) or status not in ("active", "archived"):
            if isinstance(activity, list) and default_board_id:
                _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                              {"endpoint": "updateCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "status", "latency_ms": _lat_ms()}, "error")
                _save("activity_events.json", activity)
            return _err("VALIDATION_ERROR", "status must be one of: active, archived", field="status")

    if not isinstance(cards, list):
        return _err("NOT_FOUND", "Cards store is unavailable")

    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                          {"endpoint": "updateCard", "status": "error", "error_code": "NOT_FOUND", "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    # Enforce default-board context (per business rules)
    if default_board_id and card.get("board_id") != default_board_id:
        # Not an authorization error; it's a server configuration restriction. Still return UNAUTHORIZED per contract codes.
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", card.get("list_id"), card_id,
                          {"endpoint": "updateCard", "status": "error", "error_code": "UNAUTHORIZED", "board_id": card.get("board_id"), "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("UNAUTHORIZED", "You don’t have access to this card in the current server configuration.", board_id=card.get("board_id"))

    # Only allow update when active, except transition to archived which is handled by archiveCard business rule.
    if card.get("status") != "active":
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", card.get("list_id"), card_id,
                          {"endpoint": "updateCard", "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": _lat_ms()}, "error")
            _save("activity_events.json", activity)
        return _err("INVALID_TRANSITION", "Only active cards can be updated.", current_status=card.get("status"))

    # Status transitions: active -> archived allowed; archived -> active not allowed here.
    if status == "archived":
        # perform archive semantics consistent with constraints
        card["status"] = "archived"
        card["archived_at"] = now
        card["updated_at"] = now
        _save("cards.json", cards)
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.archived", card.get("list_id"), card_id,
                          {"endpoint": "updateCard", "archived_via": "status_field", "latency_ms": _lat_ms()}, "ok")
            _save("activity_events.json", activity)
        return {"card": card}

    changed = {}
    if title is not None and title != card.get("title"):
        changed["title"] = {"from": card.get("title"), "to": title}
        card["title"] = title
    if description is not None and description != card.get("description"):
        changed["description"] = {"from": card.get("description"), "to": description}
        card["description"] = description
    if position is not None and position != card.get("position"):
        changed["position"] = {"from": card.get("position"), "to": position}
        card["position"] = float(position)
    if due_at is not None:
        # explicit set/clear
        if parsed_due != card.get("due_at"):
            changed["due_at"] = {"from": card.get("due_at"), "to": parsed_due}
            card["due_at"] = parsed_due

    if not changed:
        # Idempotent: still write a request/audit marker but don't mutate store.
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", card.get("list_id"), card_id,
                          {"endpoint": "updateCard", "changed_fields": [], "latency_ms": _lat_ms()}, "ok")
            _save("activity_events.json", activity)
        return {"card": card}

    card["updated_at"] = now
    _save("cards.json", cards)
    if isinstance(activity, list) and default_board_id:
        _log_activity(activity, default_board_id, actor_id, "card.updated", card.get("list_id"), card_id,
                      {"endpoint": "updateCard", "changed_fields": list(changed.keys()), "changes": changed, "latency_ms": _lat_ms()}, "ok")
        _save("activity_events.json", activity)
    return {"card": card}

def moveCard(card_id, list_id, position=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        import secrets
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + secrets.token_hex(6).upper()

    def _find_default_board(boards_rows):
        if not isinstance(boards_rows, list):
            return None
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True and x.get("status") == "active"), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("status") == "active"), None)
        if b:
            return b
        return boards_rows[0] if boards_rows else None

    def _find_actor(members_rows):
        if not isinstance(members_rows, list):
            return None
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if a:
            return a
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("status") == "active"), None)
        if a:
            return a
        return members_rows[0] if members_rows else None

    def _log_activity(activity_rows, board_id, actor_id, event_type, list_id_val, card_id_val, payload):
        if not isinstance(activity_rows, list):
            return
        activity_rows.append({
            "id": _new_id("trl_act_"),
            "board_id": board_id,
            "actor_member_id": actor_id,
            "event_type": event_type,
            "list_id": list_id_val,
            "card_id": card_id_val,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        })

    boards = _load("boards.json")
    members = _load("members.json")
    lists = _load("lists.json")
    cards = _load("cards.json")
    activity = _load("activity_events.json")

    default_board = _find_default_board(boards)
    actor = _find_actor(members)
    actor_id = actor.get("id") if isinstance(actor, dict) else None
    default_board_id = default_board.get("id") if isinstance(default_board, dict) else None

    # Validate
    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-Z]{18,}$", card_id):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", None, None,
                          {"endpoint": "moveCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "card_id", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "card_id must be a valid trl_crd_... id", field="card_id")

    if not isinstance(list_id, str) or not re.match(r"^trl_lst_[0-9A-Z]{18,}$", list_id):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", None, card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "list_id", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "list_id must be a valid trl_lst_... id", field="list_id")

    if position is not None and (not isinstance(position, (int, float)) or isinstance(position, bool)):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", None, card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "position", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "position must be a number when provided", field="position")

    if not isinstance(cards, list):
        return _err("NOT_FOUND", "Cards store is unavailable")
    if not isinstance(lists, list):
        return _err("NOT_FOUND", "Lists store is unavailable")

    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", None, card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "NOT_FOUND", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    dest_list = next((l for l in lists if isinstance(l, dict) and l.get("id") == list_id), None)
    if not dest_list:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", None, card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "NOT_FOUND", "list_id": list_id, "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Destination list not found", list_id=list_id)

    # Enforce lifecycle and board integrity rules
    if card.get("status") != "active":
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", card.get("list_id"), card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("INVALID_TRANSITION", "Archived cards cannot be moved.", current_status=card.get("status"))

    if dest_list.get("status") != "active":
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", dest_list.get("id"), card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("INVALID_TRANSITION", "Destination list is archived.", list_id=list_id)

    # Server configured board restriction (default board)
    if default_board_id:
        if card.get("board_id") != default_board_id or dest_list.get("board_id") != default_board_id:
            if isinstance(activity, list):
                _log_activity(activity, default_board_id, actor_id, "card.moved", dest_list.get("id"), card_id,
                              {"endpoint": "moveCard", "status": "error", "error_code": "UNAUTHORIZED",
                               "card_board_id": card.get("board_id"), "dest_board_id": dest_list.get("board_id"),
                               "latency_ms": _lat_ms()})
                _save("activity_events.json", activity)
            return _err("UNAUTHORIZED", "You don’t have access to the card or destination list in the current server configuration.", board_id=default_board_id)

    # Must remain on same board
    if card.get("board_id") != dest_list.get("board_id"):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", dest_list.get("id"), card_id,
                          {"endpoint": "moveCard", "status": "error", "error_code": "VALIDATION_ERROR", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "Destination list must be on the same board as the card.", rule="cards.board_id must equal lists.board_id")

    from_list_id = card.get("list_id")
    to_list_id = dest_list.get("id")

    # Compute position if not provided
    if position is None:
        max_pos = None
        for c in cards:
            if isinstance(c, dict) and c.get("status") == "active" and c.get("list_id") == to_list_id:
                p = c.get("position")
                if isinstance(p, (int, float)) and not isinstance(p, bool):
                    max_pos = p if max_pos is None else max(max_pos, p)
        position = 0.0 if max_pos is None else float(max_pos) + 1.0

    # Idempotent if no actual change
    if card.get("list_id") == to_list_id and float(card.get("position", 0.0)) == float(position):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.moved", to_list_id, card_id,
                          {"endpoint": "moveCard", "from_list_id": from_list_id, "to_list_id": to_list_id, "idempotent": True, "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return {"card": card}

    card["list_id"] = to_list_id
    card["position"] = float(position)
    card["updated_at"] = now
    _save("cards.json", cards)

    if isinstance(activity, list) and (default_board_id or card.get("board_id")):
        _log_activity(activity, (default_board_id or card.get("board_id")), actor_id, "card.moved", to_list_id, card_id,
                      {"endpoint": "moveCard", "from_list_id": from_list_id, "to_list_id": to_list_id, "position": float(position), "latency_ms": _lat_ms()})
        _save("activity_events.json", activity)

    return {"card": card}

