        a = next((m for m in members_rows if isinstance(m, dict) and m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if a:
            return a
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("status") == "active"), None)
        if a:
            return a
        return members_rows[0] if members_rows else None

    def _log_activity(activity_rows, board_id, actor_id, event_type, list_id_val, card_id_val, payload):
        if not isinstance(activity_rows, list):
            return
        activity_rows.append({
            "id": _new_id("trl_act_"),
            "board_id": board_id,
            "actor_member_id": actor_id,
            "event_type": event_type,
            "list_id": list_id_val,
            "card_id": card_id_val,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        })

    boards = _load("boards.json")
    members = _load("members.json")
    cards = _load("cards.json")
    card_members = _load("card_members.json")
    activity = _load("activity_events.json")

    default_board = _find_default_board(boards)
    actor = _find_actor(members)
    actor_id = actor.get("id") if isinstance(actor, dict) else None
    default_board_id = default_board.get("id") if isinstance(default_board, dict) else None

    # Validate
    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-Z]{18,}$", card_id):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", None, None,
                          {"endpoint": "changeCardMembers", "status": "error", "error_code": "VALIDATION_ERROR", "field": "card_id", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "card_id must be a valid trl_crd_... id", field="card_id")

    if not isinstance(member_ids, list):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", None, card_id,
                          {"endpoint": "changeCardMembers", "status": "error", "error_code": "VALIDATION_ERROR", "field": "member_ids", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "member_ids must be an array", field="member_ids")

    for mid in member_ids:
        if not isinstance(mid, str) or not re.match(r"^trl_mem_[0-9A-Z]{18,}$", mid):
            if isinstance(activity, list) and default_board_id:
                _log_activity(activity, default_board_id, actor_id, "card.members.changed", None, card_id,
                              {"endpoint": "changeCardMembers", "status": "error", "error_code": "VALIDATION_ERROR", "field": "member_ids", "bad_member_id": mid, "latency_ms": _lat_ms()})
                _save("activity_events.json", activity)
            return _err("VALIDATION_ERROR", "Each member_id must be a valid trl_mem_... id", field="member_ids", member_id=mid)

    if not isinstance(cards, list):
        return _err("NOT_FOUND", "Cards store is unavailable")
    if not isinstance(card_members, list):
        return _err("NOT_FOUND", "Card members store is unavailable")
    if not isinstance(members, list):
        return _err("NOT_FOUND", "Members store is unavailable")

    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", None, card_id,
                          {"endpoint": "changeCardMembers", "status": "error", "error_code": "NOT_FOUND", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    # Server configured board restriction (default board)
    if default_board_id and card.get("board_id") != default_board_id:
        if isinstance(activity, list):
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", card.get("list_id"), card_id,
                          {"endpoint": "changeCardMembers", "status": "error", "error_code": "UNAUTHORIZED", "board_id": card.get("board_id"), "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("UNAUTHORIZED", "You don’t have access to this card in the current server configuration.", board_id=card.get("board_id"))

    if card.get("status") != "active":
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", card.get("list_id"), card_id,
                          {"endpoint": "changeCardMembers", "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("INVALID_TRANSITION", "Cannot change members of an archived card.", current_status=card.get("status"))

    # Ensure referenced members exist (FK restrict semantics)
    members_by_id = {m.get("id"): m for m in members if isinstance(m, dict) and isinstance(m.get("id"), str)}
    for mid in member_ids:
        if mid not in members_by_id:
            if isinstance(activity, list) and default_board_id:
                _log_activity(activity, default_board_id, actor_id, "card.members.changed", card.get("list_id"), card_id,
                              {"endpoint": "changeCardMembers", "status": "error", "error_code": "NOT_FOUND", "missing_member_id": mid, "latency_ms": _lat_ms()})
                _save("activity_events.json", activity)
            return _err("NOT_FOUND", "Member not found", member_id=mid)

    desired = list(dict.fromkeys(member_ids))  # dedupe preserving order
    desired_set = set(desired)

    existing_rows = [r for r in card_members if isinstance(r, dict) and r.get("card_id") == card_id]
    active_existing = {r.get("member_id"): r for r in existing_rows if r.get("status") == "active" and isinstance(r.get("member_id"), str)}
    removed_existing = {r.get("member_id"): r for r in existing_rows if r.get("status") == "removed" and isinstance(r.get("member_id"), str)}

    added = []
    removed = []
    changed_any = False

    # Remove assignments not desired
    for mid, row in list(active_existing.items()):
        if mid not in desired_set:
            # transition active -> removed
            row["status"] = "removed"
            row["removed_at"] = now
            row["updated_at"] = now
            removed.append(mid)
            changed_any = True

    # Add (or re-activate) desired assignments
    for mid in desired:
        if mid in active_existing:
            continue
        if mid in removed_existing:
            # removed -> active transition
            row = removed_existing[mid]
            row["status"] = "active"
            row["removed_at"] = None
            row["updated_at"] = now
            added.append(mid)
            changed_any = True
        else:
            # create new
            card_members.append({
                "id": _new_id("trl_cmb_"),
                "card_id": card_id,
                "member_id": mid,
                "assigned_by_member_id": actor_id,
                "status": "active",
                "created_at": now,
                "updated_at": now,
                "removed_at": None,
            })
            added.append(mid)
            changed_any = True

    # Enforce unique(card_id, member_id) where status='active'
    # If duplicates exist in store, normalize by removing extras (mark removed) to satisfy constraints.
    seen = set()
    for r in [r for r in card_members if isinstance(r, dict) and r.get("card_id") == card_id and r.get("status") == "active"]:
        mid = r.get("member_id")
        if not isinstance(mid, str):
            continue
        if mid in seen:
            r["status"] = "removed"
            r["removed_at"] = now
            r["updated_at"] = now
            if mid not in removed:
                removed.append(mid)
            changed_any = True
        else:
            seen.add(mid)

    if not changed_any:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.members.changed", card.get("list_id"), card_id,
                          {"endpoint": "changeCardMembers", "added_member_ids": [], "removed_member_ids": [], "idempotent": True, "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        # Return current membership state
        active_member_ids = sorted({r.get("member_id") for r in card_members if isinstance(r, dict) and r.get("card_id") == card_id and r.get("status") == "active" and isinstance(r.get("member_id"), str)})
        return {"card_id": card_id, "member_ids": active_member_ids}

    _save("card_members.json", card_members)
    if isinstance(activity, list) and default_board_id:
        _log_activity(activity, default_board_id, actor_id, "card.members.changed", card.get("list_id"), card_id,
                      {"endpoint": "changeCardMembers", "added_member_ids": added, "removed_member_ids": removed, "latency_ms": _lat_ms()})
        _save("activity_events.json", activity)

    active_member_ids = sorted({r.get("member_id") for r in card_members if isinstance(r, dict) and r.get("card_id") == card_id and r.get("status") == "active" and isinstance(r.get("member_id"), str)})
    return {"card_id": card_id, "member_ids": active_member_ids}

