                          {"endpoint": "archiveCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "card_id", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "card_id must be a valid trl_crd_... id", field="card_id")

    if not isinstance(cards, list):
        return _err("NOT_FOUND", "Cards store is unavailable")

    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.archived", None, card_id,
                          {"endpoint": "archiveCard", "status": "error", "error_code": "NOT_FOUND", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    if default_board_id and card.get("board_id") != default_board_id:
        if isinstance(activity, list):
            _log_activity(activity, default_board_id, actor_id, "card.archived", card.get("list_id"), card_id,
                          {"endpoint": "archiveCard", "status": "error", "error_code": "UNAUTHORIZED", "board_id": card.get("board_id"), "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("UNAUTHORIZED", "You don’t have access to the card’s board in the current server configuration.", board_id=card.get("board_id"))

    if card.get("status") == "archived":
        # Idempotent
        if isinstance(activity, list) and (default_board_id or card.get("board_id")):
            _log_activity(activity, (default_board_id or card.get("board_id")), actor_id, "card.archived", card.get("list_id"), card_id,
                          {"endpoint": "archiveCard", "idempotent": True, "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return {"card": card}

    if card.get("status") != "active":
        if isinstance(activity, list) and (default_board_id or card.get("board_id")):
            _log_activity(activity, (default_board_id or card.get("board_id")), actor_id, "card.archived", card.get("list_id"), card_id,
                          {"endpoint": "archiveCard", "status": "error", "error_code": "INVALID_TRANSITION", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("INVALID_TRANSITION", "Card cannot be archived from its current status.", current_status=card.get("status"))

    card["status"] = "archived"
    card["archived_at"] = now
    card["updated_at"] = now
    _save("cards.json", cards)

    if isinstance(activity, list) and (default_board_id or card.get("board_id")):
        _log_activity(activity, (default_board_id or card.get("board_id")), actor_id, "card.archived", card.get("list_id"), card_id,
                      {"endpoint": "archiveCard", "latency_ms": _lat_ms()})
        _save("activity_events.json", activity)

    return {"card": card}

def addList(board_id, name, position=None, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _gen_id(prefix):
        # 20 chars base32-ish from uuid, uppercase; satisfies {18,}
        raw = uuid.uuid4().hex.upper()
        return f"{prefix}_{raw[:20]}"

    t0 = time.time()
    status = "success"

    # Validate inputs
    if not isinstance(board_id, str) or not re.match(r"^trl_brd_[0-9A-Z]{18,}$", board_id or ""):
        status = "error"
        resp = _err("VALIDATION_ERROR", "board_id is invalid.", field="board_id")
    elif not isinstance(name, str) or len(name.strip()) < 1:
        status = "error"
        resp = _err("VALIDATION_ERROR", "name is required and must be non-empty.", field="name")
    elif position is not None and not isinstance(position, (int, float)) or isinstance(position, bool):
        status = "error"
        resp = _err("VALIDATION_ERROR", "position must be a number.", field="position")
    else:
        boards = _load("boards.json")
        members = _load("members.json")
        lists = _load("lists.json")
        events = _load("activity_events.json")

        # Resolve ambient auth: must have an authenticated active member.
        authed = next((m for m in members if m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if not authed:
            status = "error"
            resp = _err("UNAUTHORIZED", "No authenticated user context is available.")

        else:
            board = next((b for b in boards if b.get("id") == board_id), None)
            if not board:
                status = "error"
                resp = _err("NOT_FOUND", "Board not found.", board_id=board_id)
            else:
                # Business rule: tools operate on default board unless internal override.
                # Since this surface accepts board_id, treat it as override but require it to be the default board.
                if board.get("default") is not True:
                    status = "error"
                    resp = _err("UNAUTHORIZED", "You don’t have access to this board in the current server configuration.", board_id=board_id)
                elif board.get("status") != "active":
                    status = "error"
                    resp = _err("INVALID_TRANSITION", "Cannot add list to a closed board.", board_id=board_id)
                else:
                    nm = name.strip()

                    # Constraint: unique(board_id, name) where status='active'
                    if any(l for l in lists if l.get("board_id") == board_id and l.get("status") == "active" and (l.get("name") or "") == nm):
                        status = "error"
                        resp = _err("CONFLICT", "An active list with this name already exists on the board.", board_id=board_id, name=nm)
                    else:
                        # Compute position if not provided: max+1 among lists on board (all statuses), else 0
                        if position is None:
                            pos_vals = [l.get("position") for l in lists if l.get("board_id") == board_id and isinstance(l.get("position"), (int, float)) and not isinstance(l.get("position"), bool)]
                            pos = (max(pos_vals) + 1) if pos_vals else 0
                        else:
                            pos = float(position)
                            if pos < 0:
                                status = "error"
                                resp = _err("VALIDATION_ERROR", "position must be >= 0.", field="position")
                        if status == "success":
                            now = _now_iso()
                            new_list = {
                                "id": _gen_id("trl_lst"),
                                "board_id": board_id,
                                "name": nm,
                                "position": pos,
                                "status": "active",
                                "archived_at": None,
                                "created_by_member_id": authed["id"],
                                "created_at": now,
                                "updated_at": now,
                            }

                            lists.append(new_list)

                            ev = {
                                "id": _gen_id("trl_evt"),
                                "board_id": board_id,
                                "actor_member_id": authed["id"],
                                "event_type": "list.created",
                                "list_id": new_list["id"],
                                "card_id": None,
                                "payload": {"name": nm, "position": pos},
                                "created_at": now,
                                "updated_at": now,
                            }
                            events.append(ev)

                            _save("lists.json", lists)
                            _save("activity_events.json", events)

                            resp = {"list": new_list}

    # Record activity event as request-log if available (schema doesn't specify one).
    # Observable dynamics are satisfied via activity_events for mutations already.

    # Return with minimal envelope
    return resp

def archiveList(list_id, **_extra):
    import json, os, datetime, re, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _gen_id(prefix):
        raw = uuid.uuid4().hex.upper()
        return f"{prefix}_{raw[:20]}"

    t0 = time.time()
    status = "success"

    if not isinstance(list_id, str) or not re.match(r"^trl_lst_[0-9A-Z]{18,}$", list_id or ""):
        status = "error"
        resp = _err("VALIDATION_ERROR", "list_id is invalid.", field="list_id")
    else:
        boards = _load("boards.json")
        members = _load("members.json")
        lists = _load("lists.json")
        events = _load("activity_events.json")

        authed = next((m for m in members if m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if not authed:
            status = "error"
            resp = _err("UNAUTHORIZED", "No authenticated user context is available.")
        else:
            lst = next((l for l in lists if l.get("id") == list_id), None)
            if not lst:
                status = "error"
                resp = _err("NOT_FOUND", "List not found.", list_id=list_id)
            else:
                board = next((b for b in boards if b.get("id") == lst.get("board_id")), None)
                if not board:
                    status = "error"
                    resp = _err("NOT_FOUND", "Board for list not found.", board_id=lst.get("board_id"))
                else:
                    if board.get("default") is not True:
                        status = "error"
                        resp = _err("UNAUTHORIZED", "You don’t have access to this list’s board in the current server configuration.", board_id=board.get("id"))
                    else:
                        cur = lst.get("status")
                        if cur != "active":
                            # No success without effect: already archived -> NOT_FOUND is wrong; treat as INVALID_TRANSITION
                            status = "error"
                            resp = _err("INVALID_TRANSITION", "List cannot be archived from its current status.", from_status=cur, to_status="archived")
                        else:
                            now = _now_iso()
                            lst["status"] = "archived"
                            lst["archived_at"] = now
                            lst["updated_at"] = now

                            ev = {
                                "id": _gen_id("trl_evt"),
                                "board_id": board["id"],
                                "actor_member_id": authed["id"],
                                "event_type": "list.archived",
                                "list_id": lst["id"],
                                "card_id": None,
                                "payload": {"list_id": lst["id"], "name": lst.get("name")},
                                "created_at": now,
                                "updated_at": now,
                            }
                            events.append(ev)

                            _save("lists.json", lists)
                            _save("activity_events.json", events)
                            resp = {"list": lst}

    return resp

def getMyCards(board_id=None, status=None, due_before=None, due_after=None, updated_after=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _parse_dt(v, field):
        if v is None:
            return None
        if not isinstance(v, str):
            return "BAD"
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return "BAD"

    def _dt_from_row(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if s.endswith("Z"):
            s = s[:-1] + "+00:00"
        try:
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _encode_cursor(i):
        return base64.urlsafe_b64encode(f"i:{i}".encode("utf-8")).decode("ascii").rstrip("=")

    def _decode_cursor(c):
        if c is None:
            return 0
        if not isinstance(c, str) or not c:
            return "BAD"
        pad = "=" * (-len(c) % 4)
        try:
            raw = base64.urlsafe_b64decode((c + pad).encode("ascii")).decode("utf-8")
        except Exception:
            return "BAD"
        if not raw.startswith("i:"):
            return "BAD"
        try:
            i = int(raw[2:])
            return i if i >= 0 else "BAD"
        except Exception:
            return "BAD"

    # Validate parameters
    if board_id is not None:
        if not isinstance(board_id, str) or not re.match(r"^trl_brd_[0-9A-Z]{18,}$", board_id or ""):
            return _err("VALIDATION_ERROR", "board_id is invalid.", field="board_id")

    if status is not None and status not in ("active", "archived"):
        return _err("VALIDATION_ERROR", "status is invalid.", field="status")

    dt_due_before = _parse_dt(due_before, "due_before")
    if dt_due_before == "BAD":
        return _err("VALIDATION_ERROR", "due_before must be an RFC3339 date-time string.", field="due_before")

    dt_due_after = _parse_dt(due_after, "due_after")
    if dt_due_after == "BAD":
        return _err("VALIDATION_ERROR", "due_after must be an RFC3339 date-time string.", field="due_after")

    dt_updated_after = _parse_dt(updated_after, "updated_after")
    if dt_updated_after == "BAD":
        return _err("VALIDATION_ERROR", "updated_after must be an RFC3339 date-time string.", field="updated_after")

    if limit is None:
        lim = 50
    else:
        if not isinstance(limit, int) or isinstance(limit, bool) or limit < 1 or limit > 100:
            return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
        lim = limit

    start = _decode_cursor(cursor)
    if start == "BAD":
        return _err("VALIDATION_ERROR", "cursor is invalid.", field="cursor")

    if sort is None:
        sort_field = "updated_at"
    else:
        if sort not in ("created_at", "updated_at", "due_at", "position"):
            return _err("VALIDATION_ERROR", "sort is invalid.", field="sort")
        sort_field = sort

    if order is None:
        sort_dir = "desc"
    else:
        if order not in ("asc", "desc"):
            return _err("VALIDATION_ERROR", "order is invalid.", field="order")
        sort_dir = order

    boards = _load("boards.json")
    members = _load("members.json")
    lists = _load("lists.json")
    cards = _load("cards.json")
    card_members = _load("card_members.json")

    authed = next((m for m in members if m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
    if not authed:
        return _err("UNAUTHORIZED", "No authenticated user context is available.")

    # Default board
    default_board = next((b for b in boards if b.get("default") is True), None)
    if not default_board:
        return {"cards": [], "page": {"limit": lim, "total": 0, "has_more": False, "next_cursor": None}}

    # Restrict to default board unless provided board_id matches it
    if board_id is not None and board_id != default_board.get("id"):
        return _err("UNAUTHORIZED", "You don’t have access to this board in the current server configuration.", board_id=board_id)

    board_filter_id = default_board.get("id")

    # Assigned cards: exists active card_members row for authed member
    assigned_card_ids = {cm.get("card_id") for cm in card_members if cm.get("status") == "active" and cm.get("member_id") == authed.get("id")}
    rows = [c for c in cards if c.get("id") in assigned_card_ids and c.get("board_id") == board_filter_id]

    # Status filter; business rule: archived excluded from getMyCards, but tool allows status filter.
    # Enforce business rule by defaulting to active and allowing archived only if explicitly requested.
    if status is None:
        rows = [c for c in rows if c.get("status") == "active"]
    else:
        rows = [c for c in rows if c.get("status") == status]

    # due filters apply to due_at (only cards with due_at not null)
    if dt_due_before is not None:
        rows = [c for c in rows if (_dt_from_row(c.get("due_at")) is not None and _dt_from_row(c.get("due_at")) < dt_due_before)]
    if dt_due_after is not None:
        rows = [c for c in rows if (_dt_from_row(c.get("due_at")) is not None and _dt_from_row(c.get("due_at")) > dt_due_after)]
    if dt_updated_after is not None:
        rows = [c for c in rows if (_dt_from_row(c.get("updated_at")) is not None and _dt_from_row(c.get("updated_at")) > dt_updated_after)]

    # Sort
    def _sort_key(c):
        if sort_field in ("created_at", "updated_at", "due_at"):
            dt = _dt_from_row(c.get(sort_field))
            # None sorts last in asc, first in desc by using sentinel
            if dt is None:
                return (1, datetime.datetime.min.replace(tzinfo=datetime.timezone.utc))
            return (0, dt)
        if sort_field == "position":
            p = c.get("position")
            if isinstance(p, (int, float)) and not isinstance(p, bool):
                return (0, float(p))
            return (1, float("inf"))
        return (0, 0)

    reverse = (sort_dir == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    total = len(rows)
    page_rows = rows[start:start + lim]
    next_i = start + lim
    has_more = next_i < total
    next_cursor = _encode_cursor(next_i) if has_more else None

    return {
        "cards": page_rows,
        "page": {
            "limit": lim,
            "total": total,
            "has_more": has_more,
            "next_cursor": next_cursor,
        },
    }

def getCard(card_id, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0224000" if __import__("os").path.isdir("./environment_mix/0224000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _lat_ms():
        return int((time.time() - t0) * 1000)

    def _new_id(prefix):
        import secrets
        return prefix + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S") + secrets.token_hex(6).upper()

    def _find_default_board(boards_rows):
        if not isinstance(boards_rows, list):
            return None
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True and x.get("status") == "active"), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("default") is True), None)
        if b:
            return b
        b = next((x for x in boards_rows if isinstance(x, dict) and x.get("status") == "active"), None)
        if b:
            return b
        return boards_rows[0] if boards_rows else None

    def _find_actor(members_rows):
        if not isinstance(members_rows, list):
            return None
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("is_authenticated_user") is True and m.get("status") == "active"), None)
        if a:
            return a
        a = next((m for m in members_rows if isinstance(m, dict) and m.get("status") == "active"), None)
        if a:
            return a
        return members_rows[0] if members_rows else None

    def _log_activity(activity_rows, board_id, actor_id, event_type, list_id_val, card_id_val, payload):
        # No read event type; use card.updated with endpoint marker (as prior code did), but don't mutate card.
        if not isinstance(activity_rows, list):
            return
        activity_rows.append({
            "id": _new_id("trl_act_"),
            "board_id": board_id,
            "actor_member_id": actor_id,
            "event_type": event_type,
            "list_id": list_id_val,
            "card_id": card_id_val,
            "payload": payload if isinstance(payload, dict) else {},
            "created_at": now,
            "updated_at": now,
        })

    boards = _load("boards.json")
    members = _load("members.json")
    cards = _load("cards.json")
    activity = _load("activity_events.json")

    default_board = _find_default_board(boards)
    actor = _find_actor(members)
    actor_id = actor.get("id") if isinstance(actor, dict) else None
    default_board_id = default_board.get("id") if isinstance(default_board, dict) else None

    if not isinstance(card_id, str) or not re.match(r"^trl_crd_[0-9A-Z]{18,}$", card_id):
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, None,
                          {"endpoint": "getCard", "status": "error", "error_code": "VALIDATION_ERROR", "field": "card_id", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("VALIDATION_ERROR", "card_id must be a valid trl_crd_... id", field="card_id")

    if not isinstance(cards, list):
        return _err("NOT_FOUND", "Cards store is unavailable")

    card = next((c for c in cards if isinstance(c, dict) and c.get("id") == card_id), None)
    if not card:
        if isinstance(activity, list) and default_board_id:
            _log_activity(activity, default_board_id, actor_id, "card.updated", None, card_id,
                          {"endpoint": "getCard", "status": "error", "error_code": "NOT_FOUND", "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("NOT_FOUND", "Card not found", card_id=card_id)

    if default_board_id and card.get("board_id") != default_board_id:
        if isinstance(activity, list):
            _log_activity(activity, default_board_id, actor_id, "card.updated", card.get("list_id"), card_id,
                          {"endpoint": "getCard", "status": "error", "error_code": "UNAUTHORIZED", "board_id": card.get("board_id"), "latency_ms": _lat_ms()})
            _save("activity_events.json", activity)
        return _err("UNAUTHORIZED", "You don’t have access to the card’s board in the current server configuration.", board_id=card.get("board_id"))

    if isinstance(activity, list) and (default_board_id or card.get("board_id")):
        _log_activity(activity, (default_board_id or card.get("board_id")), actor_id, "card.updated", card.get("list_id"), card_id,
                      {"endpoint": "getCard", "status": "ok", "latency_ms": _lat_ms()})
        _save("activity_events.json", activity)

    return {"card": card}
